terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.31.0"
    }
  }
  backend "s3" {
    bucket         = var.state_bucket
    key            = "vpc/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = var.state_lock_table
    encrypt        = true
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = {
      environment = var.environment
      team        = var.team
      managed-by  = "terraform"
      cost-center = var.cost_center
    }
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "5.4.0"

  name = "${var.project}-${var.environment}"
  cidr = var.vpc_cidr

  azs             = ["us-east-1a", "us-east-1b", "us-east-1c"]
  public_subnets  = [cidrsubnet(var.vpc_cidr, 4, 0), cidrsubnet(var.vpc_cidr, 4, 1), cidrsubnet(var.vpc_cidr, 4, 2)]
  private_subnets = [cidrsubnet(var.vpc_cidr, 4, 4), cidrsubnet(var.vpc_cidr, 4, 5), cidrsubnet(var.vpc_cidr, 4, 6)]
  database_subnets = [cidrsubnet(var.vpc_cidr, 4, 8), cidrsubnet(var.vpc_cidr, 4, 9), cidrsubnet(var.vpc_cidr, 4, 10)]

  enable_nat_gateway     = true
  single_nat_gateway     = var.environment != "production"
  one_nat_gateway_per_az = var.environment == "production"

  enable_flow_log                      = true
  create_flow_log_cloudwatch_log_group = true
  create_flow_log_iam_role             = true
  flow_log_max_aggregation_interval    = 60

  enable_dns_hostnames = true
  enable_dns_support   = true
}

# Bastion host in public subnet with SSM access
module "bastion" {
  source = "./modules/bastion"
  vpc_id = module.vpc.vpc_id
  subnet_id = module.vpc.public_subnets[0]
  allowed_cidrs = var.bastion_allowed_cidrs
  instance_type = "t3.micro"
  key_name = var.bastion_key_name
}

files.variables.tf:
variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region for all resources"
  validation {
    condition     = can(regex("^us-(east|west)-[12]$", var.aws_region))
    error_message = "Region must be a valid US region."
  }
}

variable "vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "CIDR block for the VPC"
}

variable "environment" {
  type        = string
  description = "Deployment environment (dev, staging, production)"
  validation {
    condition     = contains(["dev", "staging", "production"], var.environment)
    error_message = "Environment must be dev, staging, or production."
  }
}

variable "project" {
  type        = string
  description = "Project name for resource naming"
}

variable "team" {
  type        = string
  description = "Team owning this infrastructure"
}

variable "cost_center" {
  type        = string
  description = "Cost center for billing allocation"
}

variable "bastion_allowed_cidrs" {
  type        = list(string)
  default     = []
  description = "CIDR blocks allowed to SSH to bastion (use VPN CIDR, never 0.0.0.0/0)"
}

variable "bastion_key_name" {
  type        = string
  description = "EC2 key pair name for bastion host"
}

files.outputs.tf:
output "vpc_id" {
  value = module.vpc.vpc_id
}

output "public_subnet_ids" {
  value = module.vpc.public_subnets
}

output "private_subnet_ids" {
  value = module.vpc.private_subnets
}

output "database_subnet_ids" {
  value = module.vpc.database_subnets
}

output "nat_gateway_ips" {
  value = module.vpc.nat_public_ips
}

