import * as pulumi from '@pulumi/pulumi';
import * as gcp from '@pulumi/gcp';

const config = new pulumi.Config();
const project = gcp.config.project!;
const region = config.require('region');
const dbPassword = config.requireSecret('dbPassword');
const customDomain = config.require('customDomain');
const imageTag = config.require('imageTag');

// VPC for private Cloud SQL access
const network = new gcp.compute.Network('app-network', { autoCreateSubnetworks: false });
const subnet = new gcp.compute.Subnetwork('app-subnet', {
  network: network.id,
  ipCidrRange: '10.0.0.0/24',
  region: region,
});

// Cloud SQL PostgreSQL
const dbInstance = new gcp.sql.DatabaseInstance('app-db', {
  databaseVersion: 'POSTGRES_15',
  region: region,
  settings: {
    tier: 'db-f1-micro',
    ipConfiguration: {
      ipv4Enabled: false,
      privateNetwork: network.id,
    },
    backupConfiguration: {
      enabled: true,
      startTime: '03:00',
    },
  },
  deletionProtection: true,
});

const db = new gcp.sql.Database('app-database', { instance: dbInstance.name, name: 'appdb' });

const dbUser = new gcp.sql.User('app-user', {
  instance: dbInstance.name,
  name: 'appuser',
  password: dbPassword,
});

// Cloud Run service
const service = new gcp.cloudrunv2.Service('app-service', {
  location: region,
  template: {
    containers: [{
      image: pulumi.interpolate`gcr.io/${project}/app:${imageTag}`,
      envs: [
        { name: 'DATABASE_URL', value: pulumi.interpolate`postgresql://appuser:${dbPassword}@${dbInstance.privateIpAddress}:5432/appdb` },
      ],
      resources: { limits: { cpu: '1', memory: '512Mi' } },
    }],
    vpcAccess: { connector: vpcConnector.id },
    scaling: { minInstanceCount: 1, maxInstanceCount: 10 },
  },
});

export const serviceUrl = service.uri;
export const dbConnectionName = dbInstance.connectionName;

